  const Poem(
    id: 'e63c19cc-5ed8-425f-b6aa-0056e3aa4c45',
    poetId: 'ef0f434c-c5a7-4cdd-b13a-35f999319fbf',
    title: '''Ба дигар халқу хеш напсандӣ.''',
    text: '''Ба дигар халқу хеш напсандӣ.
Бар дигар мардумон ҳамон андеш,
Ки нанолӣ гар оядат дар пеш».
Панди худ боз гуфт сар то сар,
Баъд аз он хост чизе аз паси дар.
Соҳиби хона меҳтари деҳ буд,
Мулку молаш зи дигарон беҳ буд.
Гуфт меҳтар ба мардуми хона:''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''book5_chunk_book5_ad.json''', pdfPage: 0),
    ],
