    poetId: 'ef0f434c-c5a7-4cdd-b13a-35f999319fbf',
    title: '''дар ҳама шаҳр.''',
    text: '''дар ҳама шаҳр.
Ҳама ҷо гуфтугӯйи Ҳотам буд,
Халқро рӯ ба сӯйи Ҳотам буд.
Подшоҳе зи хусравони араб,
Арабе сӯйи хеш кард талаб.
Ки: «Зи Ҳотам ба ҷон расида дилам,
Пеши мардум зи ҷуди ӯ хиҷилам''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''book5_chunk_book5_ad.json''', pdfPage: 0),
