    poetId: 'f09073cb-33b4-4fcc-abf8-75959350245c',
    title: '''Надонам, к-ин ҳама тарки адаб ...''',
    text: '''Надонам, к-ин ҳама тарки адаб чист?
Ҳади худро намедонӣ, сабаб чист?
Адаб хоҳӣ, зи ҳад берун манеҳ пой,
Зи ҳар ҷониб, ки хоҳӣ дар миён ой.
Адаб ороиши афъол бошад,
Адаб осоиши аҳвол бошад.
Фурӯғи зоҳир''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''book5_chunk_book5_ad.json''', pdfPage: 0),
    ],
