    title: '''Зи байни абрҳо қасри кабуде,''',
    text: '''Зи байни абрҳо қасри кабуде,
Кабуду дилписанду хушнамуде.
Намоён гашт:
Ҳайронам, чӣ бошад?
Агар қаср аст вай, пас аз кӣ бошад?
Магар ин гунбади Тоҷи маҳал''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_ag.json''', pdfPage: 0),
