    poetId: '9a3f7c2a-a41d-4064-9ea7-766941c9ae35',
    title: '''Он шунидастӣ, ки дар саҳрои Ғӯ...''',
    text: '''Он шунидастӣ, ки дар саҳрои Ғӯр,
Борсолоре бияфтод аз сутур.
Гуфт: – «Чашми танги дунёдорро,
Ё қаноат пур кунад, ё хоки гӯр! »''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''book5_chunk_book5_ac.json''', pdfPage: 0),
