    title: '''Ба даст оҳаки тафта кардан хам...''',
    text: '''Ба даст оҳаки тафта кардан хамир,
Беҳ аз даст бар сина пеши амир.''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''book5_chunk_book5_ac.json''', pdfPage: 0),
    ],
  ),
  const Poem(
