    poetId: '2e7a713f-c3d2-449e-bd6a-a4b5b7350201',
    title: '''асту беоб,''',
    text: '''асту беоб,
Аҳолӣ ҷоҳилу дар бистари хоб.
Гар аз Ҷайҳун ду-се ҷӯ ҳафр''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_aa.json''', pdfPage: 0),
    ],
  ),
  const Poem(
