    title: '''Намунаҳо аз қасидаҳо''',
    text: '''Бад-ин хуррамӣ ҷаҳон, бад-ин тозагӣ баҳор,
Бад-ин равшанӣ шароб, бад-ин накуӣ нигор.
Яке чун биҳишти адн
яке чун ҳавои дӯст,
