    poetId: '465d3f4a-4924-4ca6-9371-7266ae4393c7',
    title: '''ДИЛ ЗАБОНИ ШИКВА ПЕШИ МАН ЗИ САХТӢ БОЗ КАРД''',
    text: '''Дил забони шиква пеши ман зи сахтӣ боз кард,
