  ),
  const Poem(
    id: 'c646d8bf-974d-40b9-b124-da3be8c1565e',
    poetId: '22097ef5-9ab2-4b03-a971-e62927f2f8c8',
    title: '''Юсуф ва Зулайхо (порча)''',
    text: '''Сафеҳе қарз карду дод ришват,
Ки гирад аз шаҳаншоҳӣ вазорат.
Басе шуд ҳалқаи дарҳои баста,
