  const Poem(
    id: '8520c43b-073e-47b1-93e3-e10448c73fb1',
    poetId: '32624545-f720-4267-9669-d3648b7369ac',
    title: '''БАНДАГӢ ДАРКОР НЕСТ''',
    text: '''Зиндагӣ охир cap ояд, бандагӣ даркор нест,
