    poetId: '41c86281-0423-4553-91e8-5f8c298ed40f',
    title: '''Зан агар оташ намешуд, хом мем...''',
    text: '''Зан агар оташ намешуд, хом мемондем мо,
Норасида бодае дар ҷом мемондем мо.''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_ae.json''', pdfPage: 0),
    ],
  ),
  const Poem(
