    title: '''Зан агар оташ намешуд, хонаи м...''',
    text: '''Зан агар оташ намешуд, хонаи мо сард буд,
Бе чароғи равшане дар шом мемондем мо.''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_ae.json''', pdfPage: 0),
