    poetId: '41c86281-0423-4553-91e8-5f8c298ed40f',
    title: '''Гар ба чашми мо намедӯшид мода...''',
    text: '''Гар ба чашми мо намедӯшид модар шири хеш,
Кӯри модарзод дар айём мемондем мо.''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_ae.json''', pdfPage: 0),
