  const Poem(
    id: 'd92d9d5c-9cdd-4428-93cd-79191ecc3112',
    poetId: '41c86281-0423-4553-91e8-5f8c298ed40f',
    title: '''Шодам, аммо мехӯрам ғамҳои хал...''',
    text: '''Шодам, аммо мехӯрам ғамҳои халқи дигаре,
Дар назар меоварам тороҷгашта кишваре.
Халқи ҳиндуи ситамкашро расон аз мо салом,
Эй суруди ман, агар дорӣ ту ҳам болу паре!''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_ae.json''', pdfPage: 0),
