    poetId: '41c86281-0423-4553-91e8-5f8c298ed40f',
    title: '''Магар ин каста авлоди башар не...''',
    text: '''Магар ин каста авлоди башар нест,
Ки аз ӯ дигаронро ҷуз ҳазар нест?
Магар ин расм як расми қадим аст?
Магар чухра гунаҳкори азим аст?...''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_ae.json''', pdfPage: 0),
    ],
  ),
  const Poem(
