    poetId: '41c86281-0423-4553-91e8-5f8c298ed40f',
    title: '''Ҳар чӣ бошад, бузургрӯд астӣ,''',
    text: '''Ҳар чӣ бошад, бузургрӯд астӣ,
Ҳиссаи баҳри беҳудуд астӣ.''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_ae.json''', pdfPage: 0),
