    title: '''Рӯдворона зиндагонӣ кун!''',
    text: '''Рӯдворона зиндагонӣ кун!
Ҷӯш зан,
Ҷӯш зан,
Ҷавонӣ кун!''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''chunk_book11_ae.json''', pdfPage: 0),
