    poetId: 'e9eed14e-8d54-4182-8d4e-731896fb30e0',
    title: '''Дар сари қабри ту гиряд аз ҷуд...''',
    text: '''Дар сари қабри ту гиряд аз ҷудоиҳо баҳор,
