  const Poem(
    id: '480500c5-d6c2-4f18-8c23-8b3adfd5119b',
    poetId: '41c86281-0423-4553-91e8-5f8c298ed40f',
    title: '''Тифл мондам аз ту, модар, рӯйи...''',
    text: '''Тифл мондам аз ту, модар, рӯйи ту дар ёд нест,
Қомати ту, чашми ту, абрӯйи ту дар ёд нест.
Дар суроғат мезанам худро ба ҳар як кӯю дар,
Чунки то имрӯз, модар, кӯйи ту дар ёд нест.''',
    isExcerpt: false,
    sourceRefs: [
      const SourceRef(bookTitle: '''book5_chunk_book5_af.json''', pdfPage: 0),
    ],
